import os
import re
import numpy as np
import logging

logger = logging.getLogger(__name__)

from .utils import format_str, find_func_in_module
from .utils import get_func_inputs_outputs_with_attrs, get_clostest_pow2

header = """
//=============================================================================
// Auto generated by ST-Flow
//=============================================================================

#include <iostream>
#include <vector>
#include <cstdint>
#include <tapa.h>
#include <algorithm>
#include <ap_axi_sdata.h>
#include <ap_int.h>
#include <cstring>
#include <hls_stream.h>
#include <hls_vector.h>
#include <random>
#include <iomanip>
#include <fstream>

#include <gflags/gflags.h>

using namespace std;

using std::clog;
using std::endl;
using std::vector;
"""

# Define gflags for bitstream
gflags_def = """
DEFINE_string(bitstream, "", "path to bitstream file, run csim if empty");
"""

main_header = """
int main(int argc, char* argv[]) {
  gflags::ParseCommandLineFlags(&argc, &argv, /*remove_flags=*/true);
"""

dtype_size_map = {
    "int8": 1,
    "int16": 2,
    "int32": 4,
    "int64": 8,
    "uint8": 1,
    "uint16": 2,
    "uint32": 4,
    "uint64": 8,
    "float16": 2,
    "float32": 4,
    "float64": 8,
}

ctype_map = {
    "bf16": "std::bfloat16_t",
    "f32": "float",
    "f64": "double",
    "i8": "int8_t",
    "i16": "short",
    "i32": "int",
    "i64": "long",
    "i128": "__int128_t",  # unverified
    "ui1": "bool",
    "ui8": "uint8_t",
    "ui16": "unsigned short",
    "ui32": "unsigned int",
    "ui64": "unsigned long",
}

def parse_vector_type(dtype):
    """
    Parse vector types like "vector<4xf32>" into (element_type, size).
    Returns (element_type, size) if it's a vector type, None otherwise.
    """
    if dtype.startswith("vector<") and dtype.endswith(">"):
        # Extract content between < and >
        content = dtype[7:-1]  # Remove "vector<" and ">"
        # Pattern: "4xf32" -> size=4, elem_type="f32"
        if "x" in content:
            parts = content.split("x", 1)
            try:
                size = int(parts[0])
                elem_type = parts[1]
                return (elem_type, size)
            except (ValueError, IndexError):
                return None
    return None

def dtype_to_ctype(dtype, for_kernel=False):
    """
    Convert dtype string to C++ type string.
    For vector types, returns hls::vector<type, size> if for_kernel=True,
    otherwise returns the element type (for host buffers).
    """
    # Check for vector types first
    vec_info = parse_vector_type(dtype)
    if vec_info is not None:
        elem_type, size = vec_info
        elem_ctype = dtype_to_ctype(elem_type, for_kernel=False)
        if for_kernel:
            return f"hls::vector<{elem_ctype}, {size}>"
        else:
            # For host buffers, use element type (will be flattened)
            return elem_ctype
    
    # Handle regular types
    if dtype in ctype_map:
        return ctype_map[dtype]
    elif dtype.startswith("i") or dtype.startswith("ui"):
        prefix, bitwidth = dtype.split("i")
        new_int_type = f"{prefix}i{max(get_clostest_pow2(int(bitwidth)), 8)}"
        return ctype_map[new_int_type]
    elif dtype.startswith("fixed") or dtype.startswith("ufixed"):
        return "float"
    else:
        raise ValueError(f"Unsupported input type: {dtype}")

def codegen_host_tapa(top, module):
    # Try to find "module_top" first
    func = find_func_in_module(module, "module_top")
    if func is not None:
        top = "module_top"
    else:
        func = find_func_in_module(module, top)
    
    if func is None:
        try:
            mod_text = str(module)
        except Exception:
            mod_text = "<unable to stringify module>"
        raise RuntimeError(f"Function '{top}' not found in module. Module: {mod_text}")
        
    inputs, outputs, inputs_outputs = get_func_inputs_outputs_with_attrs(func)
    
    # Build a mapping to preserve original argument order
    arg_attrs = None
    for attr_p in func.attributes:
        if attr_p.name == "arg_attrs":
            arg_attrs = attr_p.attr
    
    ordered_args = []
    input_idx = 0
    output_idx = 0
    input_output_idx = 0
    
    for i, (arg, arg_attr) in enumerate(zip(func.arguments, arg_attrs)):
        buf_info = arg_attr['buffer.info']
        io = buf_info['io'].value
        if io == 'read-only':
            ordered_args.append(('input', input_idx, inputs[input_idx]))
            input_idx += 1
        elif io == 'write-only':
            ordered_args.append(('output', output_idx, outputs[output_idx]))
            output_idx += 1
        elif io == 'read-write' or io == 'unknown':
            ordered_args.append(('input_output', input_output_idx, inputs_outputs[input_output_idx]))
            input_output_idx += 1
            
    out_str = format_str(header, indent=0, strip=False)

    # Auto-detect a generated golden header and include it when present.
    golden_paths = ["golden.h", os.path.join("src", "golden.h")]
    golden_found = any(os.path.exists(p) for p in golden_paths)
    if golden_found:
        pass
        # out_str += format_str('#include "golden.h"\\n', strip=False)

    # Auto-detect a compiled golden reference implementation
    golden_ref_paths = ["golden_reference.cpp", os.path.join("src", "golden_reference.cpp")]
    golden_ref_found = any(os.path.exists(p) for p in golden_ref_paths)

    if golden_ref_found:
        proto_with_names = None
        for p in golden_ref_paths:
            if os.path.exists(p):
                try:
                    with open(p, "r", encoding="utf-8") as gf:
                        text = gf.read()
                    m = re.search(r'extern\\s+"C"\\s+void\\s+top_golden\\s*\\((.*?)\\)\\s*{', text, re.S)
                    if m:
                        proto_with_names = m.group(1).strip()
                        break
                except Exception:
                    proto_with_names = None
        if proto_with_names is not None and proto_with_names == "":
            proto_with_names = "void"
        if proto_with_names is None:
            proto_params = []
            for arg_type, idx, arg_data in ordered_args:
                dtype, shape, name, kind = arg_data
                ctype = dtype_to_ctype(dtype, for_kernel=False)
                if len(shape) == 0:
                    proto_params.append(ctype)
                else:
                    proto_params.append(f"{ctype}*")
            proto_with_names = ", ".join([f"{t} arg{idx}" for idx, t in enumerate(proto_params)]) if proto_params else "void"
        out_str += format_str(f'extern "C" void top_golden({proto_with_names});\n', strip=False)
    
    # Generate typedefs for vector types if needed
    # (This logic might need refinement based on actual types used)
    out_str += "\n"
    
    # Forward declaration of kernel function
    # We need to construct the signature for the kernel function
    kernel_args = []
    for arg_type, idx, arg_data in ordered_args:
        dtype, shape, name, kind = arg_data
        ctype = dtype_to_ctype(dtype, for_kernel=True)
            
        if len(shape) == 0:
            kernel_args.append(f"{ctype} {name}")
        else:
            # For Tapa, arrays are typically passed as tapa::mmap or similar
            # But the kernel declaration in host code usually matches the HLS function signature
            # which might use pointers or arrays.
            # However, tapa::invoke expects arguments that can be mapped to the kernel ports.
            # The reference uses `tapa::mmap<type> name` in the kernel declaration in the TB.
            kernel_args.append(f"tapa::mmap<{ctype}> {name}")

    out_str += format_str(f"void {top}(", indent=0, strip=False)
    out_str += format_str(",\n  ".join(kernel_args), indent=2, strip=False)
    out_str += format_str("\n);\n", indent=0, strip=False)
    
    out_str += format_str(gflags_def, indent=0, strip=False)
    out_str += format_str(main_header, indent=0, strip=False)
    
    # Generate host buffers and initialization
    # Inputs
    for i, (in_dtype, in_shape, in_name, in_kind) in enumerate(inputs):
        # For vector types, use element type for host buffers (will be flattened)
        in_dtype_ctype = dtype_to_ctype(in_dtype, for_kernel=False)
        # Check if original dtype was a vector type to adjust size
        vec_info = parse_vector_type(in_dtype)
        if vec_info is not None:
            elem_type, vec_size = vec_info
            # For vector types, multiply shape by vector size
            if len(in_shape) > 0:
                in_shape = tuple(list(in_shape) + [vec_size])
            in_dtype = in_dtype_ctype
        else:
            in_dtype = in_dtype_ctype
        
        if len(in_shape) == 0:
             # Scalar
            out_str += format_str(f"{in_dtype} {in_name};")
            # Initialize scalar (random or default)
            out_str += format_str(f"{in_name} = ({in_dtype})1;") # Simple init
        else:
            # Vector
            size_expr = " * ".join([str(s) for s in in_shape])
            out_str += format_str(f"vector<{in_dtype}> {in_name}({size_expr});")
            # Initialize vector
            out_str += format_str(f"for (size_t i = 0; i < {in_name}.size(); i++) {{")
            out_str += format_str(f"  {in_name}[i] = ({in_dtype})i;") # Simple init
            out_str += format_str("}")

    # Outputs
    for i, (out_dtype, out_shape, out_name, out_kind) in enumerate(outputs):
        # For vector types, use element type for host buffers (will be flattened)
        out_dtype_ctype = dtype_to_ctype(out_dtype, for_kernel=False)
        # Check if original dtype was a vector type to adjust size
        vec_info = parse_vector_type(out_dtype)
        if vec_info is not None:
            elem_type, vec_size = vec_info
            # For vector types, multiply shape by vector size
            if len(out_shape) > 0:
                out_shape = tuple(list(out_shape) + [vec_size])
            out_dtype = out_dtype_ctype
        else:
            out_dtype = out_dtype_ctype
            
        if len(out_shape) == 0:
            out_str += format_str(f"{out_dtype} {out_name};")
        else:
            size_expr = " * ".join([str(s) for s in out_shape])
            out_str += format_str(f"vector<{out_dtype}> {out_name}({size_expr});")
            
    # Inputs/Outputs
    for i, (io_dtype, io_shape, io_name, io_kind) in enumerate(inputs_outputs):
        # For vector types, use element type for host buffers (will be flattened)
        io_dtype_ctype = dtype_to_ctype(io_dtype, for_kernel=False)
        # Check if original dtype was a vector type to adjust size
        vec_info = parse_vector_type(io_dtype)
        if vec_info is not None:
            elem_type, vec_size = vec_info
            # For vector types, multiply shape by vector size
            if len(io_shape) > 0:
                io_shape = tuple(list(io_shape) + [vec_size])
            io_dtype = io_dtype_ctype
        else:
            io_dtype = io_dtype_ctype
            
        if len(io_shape) == 0:
            out_str += format_str(f"{io_dtype} {io_name};")
        else:
            size_expr = " * ".join([str(s) for s in io_shape])
            out_str += format_str(f"vector<{io_dtype}> {io_name}({size_expr});")

    out_str += "\n"

    # Golden reference execution
    if golden_ref_found:
        golden_creation = []
        golden_call_args = []
        input_idx = 0
        output_idx = 0
        input_output_idx = 0
        golden_out_counter = 0

        for arg_type, idx, arg_data in ordered_args:
            dtype, shape, name, kind = arg_data
            ctype = dtype_to_ctype(dtype, for_kernel=False)

            if arg_type == 'input':
                if len(shape) == 0:
                    golden_call_args.append(f"&{name}")
                elif len(shape) == 1:
                    golden_call_args.append(f"{name}.data()")
                elif len(shape) == 2:
                    r, c = shape
                    golden_creation.append(f"{ctype} golden_in{input_idx}[{r}][{c}];")
                    golden_creation.append(
                        f"for (unsigned __i = 0; __i < {r}; ++__i) for (unsigned __j = 0; __j < {c}; ++__j) golden_in{input_idx}[__i][__j] = {name}[__i*{c} + __j];"
                    )
                    golden_call_args.append(f"&golden_in{input_idx}[0][0]")
                else:
                    golden_call_args.append(f"{name}.data()")
                input_idx += 1

            elif arg_type == 'output':
                if len(shape) == 0:
                    golden_creation.append(f"{ctype} golden_out{golden_out_counter};")
                    golden_call_args.append(f"&golden_out{golden_out_counter}")
                elif len(shape) == 1:
                    golden_creation.append(f"vector<{ctype}> golden_out{golden_out_counter}({' * '.join(map(str, shape))});")
                    golden_creation.append(f"std::fill(golden_out{golden_out_counter}.begin(), golden_out{golden_out_counter}.end(), 0);")
                    golden_call_args.append(f"golden_out{golden_out_counter}.data()")
                elif len(shape) == 2:
                    r, c = shape
                    golden_creation.append(f"{ctype} golden_out{golden_out_counter}[{r}][{c}];")
                    golden_creation.append(f"for (unsigned __i = 0; __i < {r}; ++__i) for (unsigned __j = 0; __j < {c}; ++__j) golden_out{golden_out_counter}[__i][__j] = 0;")
                    golden_call_args.append(f"&golden_out{golden_out_counter}[0][0]")
                else:
                    golden_creation.append(f"vector<{ctype}> golden_out{golden_out_counter}({' * '.join(map(str, shape))});")
                    golden_creation.append(f"std::fill(golden_out{golden_out_counter}.begin(), golden_out{golden_out_counter}.end(), 0);")
                    golden_call_args.append(f"golden_out{golden_out_counter}.data()")
                output_idx += 1
                golden_out_counter += 1

            elif arg_type == 'input_output':
                # Skip for now as in host.py
                continue 
                
        if golden_creation:
            out_str += "\n"
            for line in golden_creation:
                out_str += format_str(line, strip=False)
        out_str += format_str("// Run golden reference on host", strip=False)
        out_str += format_str(f"top_golden({', '.join(golden_call_args)});", strip=False)
        out_str += "\n"

    out_str += format_str('clog << "Launching kernel" << endl;', indent=2)
    
    # Tapa invoke
    out_str += format_str(f"int64_t kernel_time_ns = tapa::invoke(", indent=2)
    out_str += format_str(f"{top}, FLAGS_bitstream,", indent=6)
    
    invoke_args = []
    for arg_type, idx, arg_data in ordered_args:
        dtype, shape, name, kind = arg_data
        # For kernel invoke, use element type for vector types (tapa::mmap handles it)
        ctype = dtype_to_ctype(dtype, for_kernel=False)
            
        if len(shape) == 0:
            invoke_args.append(name)
        else:
            if arg_type == 'input':
                invoke_args.append(f"tapa::read_only_mmap<{ctype}>({name})")
            elif arg_type == 'output':
                invoke_args.append(f"tapa::write_only_mmap<{ctype}>({name})")
            else:
                invoke_args.append(f"tapa::read_write_mmap<{ctype}>({name})")
                
    out_str += format_str(",\n      ".join(invoke_args), indent=6, strip=False)
    out_str += format_str("\n  );\n", indent=2, strip=False)
    
    out_str += format_str('clog << "kernel time: " << kernel_time_ns * 1e-9 << " s" << endl;', indent=2)

    # Golden verification
    if golden_ref_found:
        if len(outputs) == 0:
            pass
        else:
            # Assuming single output for now, similar to host.py limitation/simplification
            # Use the correct index for outputs (after inputs_outputs)
            final_idx = len(inputs_outputs) + len(outputs) - 1
            out_buf = outputs[0][2] # name of the first output arg
            
            out_str += format_str("// Compare golden reference output with kernel output", strip=False)
            out_str += format_str("{", strip=False)
            out_str += format_str(f"size_t __cmp_size = {out_buf}.size();", strip=False)
            out_str += format_str("if (__cmp_size == 0) { std::cout << \"Warning: empty output for comparison\" << std::endl; }", strip=False)
            out_str += format_str("for (size_t __i = 0; __i < __cmp_size; ++__i) {", strip=False)
            out_str += format_str("  double __a = (double) "+out_buf+"[__i];", strip=False)
            if len(outputs) > 0 and len(outputs[0][1]) == 2:
                cols = outputs[0][1][1]
                out_str += format_str(f"  double __b = (double) golden_out0[__i/{cols}][__i%{cols}];", strip=False)
            else:
                out_str += format_str("  double __b = (double) golden_out0[__i];", strip=False)
            out_str += format_str("  double __diff = std::abs(__a - __b);", strip=False)
            out_str += format_str("  if (__diff > 1e-3) {", strip=False)
            out_str += format_str('    std::cerr << "Mismatch at index " << __i << " kernel=" << __a << " ref=" << __b << " diff=" << __diff << std::endl;', strip=False)
            out_str += format_str("    return EXIT_FAILURE;", strip=False)
            out_str += format_str("  }", strip=False)
            out_str += format_str("}", strip=False)
            out_str += format_str("}", strip=False)
    out_str += format_str("return 0;", indent=2)
    out_str += format_str("}", indent=0)
    
    return out_str

def generate_link_config(top_func_name, kernel_code):
    """
    Generate link_config.ini content by parsing the C++ kernel code.
    Use simple string parsing to find the top function signature and extract arguments.
    """
    connectivity_content = "[connectivity]\n"
    
    # Try to find the top function signature
    # Pattern: void top_func_name(
    func_sig_start = f"void {top_func_name}("
    start_idx = kernel_code.find(func_sig_start)
    
    if start_idx == -1:
        # Try finding it with template arguments or attributes before it if necessary
        # But for now, simple search. If not found, try searching for "void module_top("
        # as a fallback if the user passed an alias, though we should prefer the passed name.
        if "module_top" != top_func_name:
             func_sig_start = "void module_top("
             start_idx = kernel_code.find(func_sig_start)
    
    if start_idx == -1:
         # Fallback: couldn't find function. Return empty or default?
         # Raising error seems safer.
         # For robustness, we can just return a comment
         return f"[connectivity]\n# Could not find function {top_func_name} in generated code\n"

    # Find the closing parenthesis
    # We need to handle nested parentheses if any (e.g. templates)
    # But TAPA top signature usually looks like:
    # void kernel_name(tapa::mmap<int> arg0, tapa::istream<float>& arg1, ...)
    
    # Start scanning after "void {name}("
    scan_idx = start_idx + len(func_sig_start)
    paren_depth = 1
    end_idx = scan_idx
    
    for i in range(scan_idx, len(kernel_code)):
        if kernel_code[i] == '(':
            paren_depth += 1
        elif kernel_code[i] == ')':
            paren_depth -= 1
            if paren_depth == 0:
                end_idx = i
                break
    
    params_str = kernel_code[scan_idx:end_idx].strip()
    
    if not params_str:
        return connectivity_content

    # Split parameters by comma, respecting templates < >
    params = []
    current_param = ""
    template_depth = 0
    
    for char in params_str:
        if char == '<':
            template_depth += 1
            current_param += char
        elif char == '>':
            template_depth -= 1
            current_param += char
        elif char == ',' and template_depth == 0:
            params.append(current_param.strip())
            current_param = ""
        else:
            current_param += char
            
    if current_param.strip():
        params.append(current_param.strip())
        
    # Extract argument names
    arg_names = []
    for param in params:
        # param looks like: tapa::mmap<int> arg0
        # or: tapa::istream<float>& arg1
        # or: const int val
        # or: tapa::mmap<float> v138 /*depth = 32*/
        
        # Remove comments if any (handle both // and /* */ style)
        if "//" in param:
            param = param.split("//")[0].strip()
        # Remove /* */ style comments
        param = re.sub(r'/\*.*?\*/', '', param).strip()
            
        # Extract all identifiers and take the last one (which should be the variable name)
        # This handles cases like "tapa::mmap<float> v138" -> "v138"
        identifiers = re.findall(r'([a-zA-Z_][a-zA-Z0-9_]*)', param)
        if identifiers:
            # The last identifier should be the variable name
            name = identifiers[-1]
            # Clean up name (remove any trailing array brackets, pointers, refs)
            name = name.lstrip("*&").rstrip("[]")
            arg_names.append(name)
            
    # Generate config
    hbm_bank = 0
    logger.info(f"arg_names: {arg_names}")
    for arg in arg_names:
        connectivity_content += f"sp={top_func_name}_1.{arg}:HBM[{hbm_bank}]\n"
        hbm_bank += 1
        
    return connectivity_content
